#!/usr/bin/env bash
# Generate gzip codec test fixtures under testdata/gzip/.
#
# Deterministic: `gzip -n` strips the original filename and timestamp
# (mtime = 0), so identical input bytes + same gzip version produce
# identical output. Regenerate with gzip >= 1.14.
set -euo pipefail

cd "$(dirname "$0")"
mkdir -p ../gzip
cd ../gzip

# --- payloads -------------------------------------------------------------
printf 'Hello, hajizip!\n' > hello.txt
printf 'Second member payload.\n' > world.txt

# --- single-member gzip (level 9, deterministic) --------------------------
gzip -n -9 -c hello.txt > hello.txt.gz

# --- multi-member gzip: two concatenated gzip members ---------------------
: > multi-member.gz
gzip -n -9 -c hello.txt >> multi-member.gz
gzip -n -9 -c world.txt >> multi-member.gz

# --- corrupt: truncated mid-stream ----------------------------------------
head -c 20 hello.txt.gz > corrupt-truncated.gz

# --- corrupt: bad CRC-32 in the trailer (flip one byte of the CRC) --------
cp hello.txt.gz corrupt-crc.gz
# Trailer is the last 8 bytes: CRC-32 (4) + ISIZE (4). Flip byte at len-8
# (the first CRC byte) so the checksum no longer matches.
size=$(stat -c%s corrupt-crc.gz 2>/dev/null || stat -f%z corrupt-crc.gz)
printf '\xff' | dd of=corrupt-crc.gz bs=1 seek=$((size - 8)) count=1 conv=notrunc 2>/dev/null


# --- manifest ---------------------------------------------------------------
cat > manifest.toml <<'EOF'
# Gzip codec fixtures. Generated by testdata/gen/gen-gzip.sh (gzip 1.14, -n).
# `decompressed_sha256` is the sha256 of the full decompressed byte stream.

[hello.txt]
size = 16
sha256 = "REPLACE"

[hello.txt.gz]
format = "gzip"
members = 1
decompressed_size = 16
decompressed_sha256 = "REPLACE"

[multi-member.gz]
format = "gzip"
members = 2
decompressed_size = 40
decompressed_sha256 = "REPLACE"

[corrupt-truncated.gz]
format = "gzip"
note = "truncated mid-stream; decompression must fail"

[corrupt-crc.gz]
format = "gzip"
note = "trailer CRC-32 corrupted; decompression must fail"
EOF

echo "generated:"
ls -l hello.txt hello.txt.gz multi-member.gz corrupt-truncated.gz corrupt-crc.gz
